INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("vo_wac_05014", "", 21, 0, "vo_wac_05014_003", 5014, 5014068, "", "", "", 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (100211, 0.5, 11, 10, "騎士クンも、本当にありがとうね。\nみんなに祝福してもらえて\nわたし、最高に幸せだよ……！\n大事に味わって食べるね！", 5014, 5014069, 1, 0, 0, 1);
