INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (105911, 0.5, 11, 10, "このケーキ……それに飾り付けは……\nみなさま！\nわたくしのために、このような……\nなんとお礼を申し上げれば……", 8614, 8614061, 1, 0, 0, 1);
