INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (106411, 0.5, 11, 10, "改めて、お誕生日おめでとう。\nコッコロさん！", 8614, 8614070, 1, 0, 0, 1);
