INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (105911, 0.5, 11, 10, "シェフィさま……！\nペコリーヌさまにキャルさま……\nそれに主さまも。\n本当に、本当にありがとうございます。", 8614, 8614075, 1, 0, 0, 1);
