INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (102711, 0.5, 11, 10, "誕生、日……？\n私のですか？\nなぜそんなことを\n覚えているのですか？", 16614, 16614068, 1, 0, 0, 1);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, "", 91, "", "", 16614, 16614069, "", "", "", "");
