INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("vo_wac_17614", "", 21, 0, "vo_wac_17614_002", 17614, 17614074, "", "", "", 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (101411, 0.5, 11, 10, "ギルドの仕事にいつも一番熱心な、\n君への労いも兼ねているよ。\n改めてお誕生日、おめでとう♪", 17614, 17614075, 1, 0, 0, 1);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, "", 91, "", "", 17614, 17614076, "", "", "", "");
