INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (100411, 0.5, 11, 10, "やったー、ありがとー！\nそれにしても、おっきい～……\n運ぶの、大変じゃなかった？", 17714, 17714067, 1, 0, 0, 1);
