INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (102011, 0.5, 11, 10, "じつは、ミミたちだけじゃ運べなくて。\nおにいちゃんも手伝ってくれたの～♪", 17714, 17714072, 1, 0, 0, 1);
