INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (105011, 0.5, 11, 10, "イオちゃん、大げさだよ～\nでも、喜んでもらえたなら、\n手作りしてよかったかも♪", 18114, 18114063, 1, 0, 0, 1);
