INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (103011, 0.5, 11, 10, "なんと、ショーグンまで！？\nみなさん、アリガトウゴザイマシタ！\nこの喜び、忍法で表現シマスよ～？\nシュバ、シュババ、シュバババ～♪", 19814, 19814101, 1, 0, 0, 1);
