INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (105911, 0.5, 11, 10, "もちろん、キャルさまのでございます。\n【美食殿】全員で心を込めて\nご用意させていただいた、特製の\n手作りケーキとなっております。", 20014, 20014080, 1, 0, 0, 1);
