INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (106011, 0.5, 11, 10, "そっか……えへへ……♪\nなら、最初っからそう言いなさいよ。\nそしたら素直にお礼だって言えるし。\n……うん、ありがとう♪", 20014, 20014085, 1, 0, 0, 1);
