INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (106411, 0.5, 11, 10, "あの、キャル……\n喜んでるところ、悪いんだけど……\nその、材料の方は、魔物の……\nペコリーヌさんが、どうしてもって……", 20014, 20014090, 1, 0, 0, 1);
