INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (118511, 0.5, 11, 10, "これは……私の誕生日ケーキですか？\nえっと、いったいどなたが……", 21014, 21014048, 1, 0, 0, 1);
