INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (101011, 0.5, 11, 10, "えっ、これって……\nうちのためのケーキどすか？\nこんなに大きくて豪華なケーキ……\nほんまに嬉しいわぁ♪", 22014, 22014063, 1, 0, 0, 1);
