INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (106611, 0.5, 11, 10, "年に一度のイノリ様の誕生日が\nきやがったですよ！\nファミリー総出で景気よく、これ以上\nないほど盛大にお祝いしやがれです！", 22714, 22714056, 1, 0, 0, 1);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, "", 91, "", "", 22714, 22714057, "", "", "", "");
