INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (102811, 0.5, 11, 10, "なに言ってるのよ、そこまでして\n用意してくれたってことでしょう？\nあんたも、来てくれてありがとう。\nずっと、みんなと仲良くしてあげてね？", 23214, 23214083, 1, 0, 0, 1);
