INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (107111, 0.5, 11, 10, "当然だな☆\nこのクリスティーナが全て段取りを\nつけたのだ、満足できないはずがない！", 25314, 25314075, 1, 0, 0, 1);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, "", 91, "", "", 25314, 25314076, "", "", "", "");
