INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (102211, 0.5, 11, 10, "わ、私たちの誕生日ケーキっ？\nいつの間にこんなものを……？", 28114, 28114074, 1, 0, 0, 1);
