INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (104411, 0.5, 11, 10, "もちろん、わらわが……と\n言いたいところじゃが、\nみんなで準備したのじゃ。\nあやつも手伝ってくれたのだぞ。", 28114, 28114079, 1, 0, 0, 1);
