INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (104711, "", 3, 1, "wac_birthday_talk_wish", 28414, 28414071, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("vo_wac_28414", "", 21, 0, "vo_wac_28414_002", 28414, 28414072, "", "", "", 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (104711, 0.5, 11, 10, "おめでとう、マツリちゃん。\n私たちだけではなく、\n少年も一緒に準備してくれたんだよ。", 28414, 28414073, 1, 0, 0, 1);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (28414073, "", 91, "", "", 28414, 28414074, "", "", "", "");
