INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (118111, 0.5, 11, 10, "これが、お誕生日ケーキ……\nす、すごく、うれしいわ……！\nわたしなんかの、ために……\nありがとう……", 31714, 31714058, 1, 0, 0, 1);
