INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (102611, 0.5, 11, 10, "そう、来年から～\nというわけで今年も一年、\nぐうたらライフで平常運転\nしていくんで、よろしく～", 32114, 32114092, 1, 0, 0, 1);
