INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (105011, 0.5, 11, 10, "ほんとだ、なんかそれっぽい！\nえへへ、写真とか撮っちゃおうかな～♪\nアンタも一緒に入る？", 32314, 32314078, 1, 0, 0, 1);
