INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (100211, 0.5, 11, 10, "大丈夫だよ。\n今のレイちゃんの顔を見たら、\nすごく喜んでくれてるって\nちゃんと分かるから♪", 33214, 33214063, 1, 0, 0, 1);
