INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, "", 91, "", "", 34314, 34314072, "", "", "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (100711, "", 3, 1, "wac_birthday_idle_smile", 34314, 34314073, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (100611, "", 3, 1, "wac_birthday_talk_smile", 34314, 34314074, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("vo_wac_34314", "", 21, 0, "vo_wac_34314_001", 34314, 34314075, "", "", "", 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (100611, 0.5, 11, 10, "もちろん、甘々で、プルプルのプリンを\nたくさん用意してきたよ～♪\n一度に頬張ったら、お口から\n垂れてきちゃうかも～♪", 34314, 34314076, 1, 0, 0, 1);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, "", 91, "", "", 34314, 34314077, "", "", "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (100611, "", 3, 1, "wac_birthday_idle_smile", 34314, 34314078, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (100711, "", 3, 1, "wac_birthday_talk_doya", 34314, 34314079, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("vo_wac_34314", "", 21, 0, "vo_wac_34314_002", 34314, 34314080, "", "", "", 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (100711, 0.5, 11, 10, "オマエたち、よくわかってるプレゼント\n本当にありがとうなの～♪\n次から誕生日だけじゃなくて、\nお盆と命日にもプリンを寄こすの～", 34314, 34314081, 1, 0, 0, 1);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, "", 91, "", "", 34314, 34314082, "", "", "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (100711, "", 3, 1, "wac_birthday_idle_doya", 34314, 34314083, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (102211, "", 3, 1, "wac_birthday_talk_sad", 34314, 34314084, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("vo_wac_34314", "", 21, 0, "vo_wac_34314_003", 34314, 34314085, "", "", "", 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (102211, 0.5, 11, 10, "ちょっと、欲張り過ぎでしょう！？\n一年に何回もこんなことしたら、\nランドソルからプリンが\n消えちゃうわよ！", 34314, 34314086, 1, 0, 0, 1);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, "", 91, "", "", 34314, 34314087, "", "", "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (102211, "", 3, 1, "wac_birthday_idle_sad", 34314, 34314088, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (103111, "", 3, 1, "wac_birthday_talk_wish", 34314, 34314089, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("vo_wac_34314", "", 21, 0, "vo_wac_34314_004", 34314, 34314090, "", "", "", 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (103111, 0.5, 11, 10, "でも、喜んでもらえてなによりです。\nミヤコさんが明るく振る舞う限り、\n穢れのない魂のまま、\n悪霊に転じることもないでしょう……", 34314, 34314091, 1, 0, 0, 1);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, "", 91, "", "", 34314, 34314092, "", "", "", "");
