INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (103611, "", 3, 1, "wac_birthday_talk_wish", 35314, 35314076, "", 0.2, "", "");
