INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (109311, 0.5, 11, 10, "うぅう～……\n甘めのケーキも、せんぱいたちも……\nあなたも、大好きですっ！！", 35514, 35514073, 1, 0, 0, 1);
