INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (103811, "", 3, 1, "wac_birthday_idle_normal", 38214, 38214072, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (103311, "", 3, 1, "wac_birthday_talk_normal", 38214, 38214073, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("vo_wac_38214", "", 21, 0, "vo_wac_38214_002", 38214, 38214074, "", "", "", 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (103311, 0.5, 11, 10, "いや、そんなことねぇよ！？\n祝ってもらってすごくうれしいけんど、\nその気持ちをどんな素晴らしいギャグで\n表現すべきか悩んでんだべ……", 38214, 38214075, 1, 0, 0, 1);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, "", 91, "", "", 38214, 38214076, "", "", "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (103311, "", 3, 1, "wac_birthday_idle_normal", 38214, 38214077, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (102611, "", 3, 1, "wac_birthday_talk_smile", 38214, 38214078, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("vo_wac_38214", "", 21, 0, "vo_wac_38214_003", 38214, 38214079, "", "", "", 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (102611, 0.5, 11, 10, "いやいや、紛らわしすぎるから。\n普通のお礼で十分でしょ、\n深刻そうなオーラ醸さないでよね？", 38214, 38214080, 1, 0, 0, 1);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, "", 91, "", "", 38214, 38214081, "", "", "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (102611, "", 3, 1, "wac_birthday_idle_smile", 38214, 38214082, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (105211, "", 3, 1, "wac_birthday_talk_smile", 38214, 38214083, "", 0.2, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("vo_wac_38214", "", 21, 0, "vo_wac_38214_004", 38214, 38214084, "", "", "", 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (105211, 0.5, 11, 10, "そうそう。\n難しい顔するより、\nみんなで楽しくおいしくケーキを\n食べましょう♪", 38214, 38214085, 1, 0, 0, 1);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, "", 91, "", "", 38214, 38214086, "", "", "", "");
