INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (103311, 0.5, 11, 10, "リマリマには、いつも助けて\nもらってるからな～\nこういう時に、しっかり\nお返ししとかねぇと！", 39314, 39314068, 1, 0, 0, 1);
