INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (102611, 0.5, 11, 10, "うんうん、ホントにね～\nリマのおかげで、\nあたしはぐうたらし放題な\nところあるしさ～", 39314, 39314073, 1, 0, 0, 1);
