INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (103811, 0.5, 11, 10, "私も、病気がちで……\nリマさんにお仕事を代わって\nもらった日もありました。\nいつも、ありがとうございます……♪", 39314, 39314078, 1, 0, 0, 1);
