INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (103211, 0.5, 11, 10, "よ、喜んでいただけたのは\nうれしいのですが……ユカリさん、\n様子がおかしくありませんこと？", 39514, 39514068, 1, 0, 0, 1);
